select vitally_private.load_intake_catalogue(2::smallint, '{"version":2,"steps":[{"n":1,"title":{"en":"Before you start","zh":"开始之前"},"sections":[{"n":0,"title":{"general":{"en":"Before You Start","zh":"开始之前"},"senior":{"en":"Before You Start","zh":"开始之前"}},"intro":{"general":{"en":"Please have these ready:\n- Tax forms you received, such as **W-2**, **1099**, **1098**, **1095**\n- **Social Security card** or **ITIN letter** for everyone on your tax return\n- **Photo ID** (such as a driver''s license) for you and your spouse\n\nYou are responsible for the information on your tax return. Please provide complete and accurate information.\nIf you are unsure about a question, choose \"I''m not sure.\" A volunteer will follow up.\n\nTo report unethical behavior by a volunteer: ts.voltax@irs.gov","zh":"请提前准备：\n- 收到的税表，如 W-2、1099、1098、1095\n- 报税表上所有人的社会安全卡或 ITIN 信\n- 您和配偶的带照片身份证件（如驾照）\n\n您需对报税表上的信息负责，请完整、准确地填写。如对某个问题不确定，请选择\"不确定\"，志愿者会跟进确认。\n\n如需举报志愿者的不当行为，请发送邮件至 ts.voltax@irs.gov"},"senior":{"en":"Please have these ready:\n- Tax papers you got in the mail, like **W-2** (from your job), **1099**, **1098**, **1095**\n- **Social Security card** or **ITIN letter** for everyone on your tax return\n- **Photo ID** (like a driver''s license) for you and your spouse\n\nYou are responsible for the information on your tax return. Please answer honestly and completely.\nIf you don''t understand a question, choose \"I''m not sure.\" A volunteer will help you.\n\nTo report unethical behavior by a volunteer: ts.voltax@irs.gov","zh":"请提前准备好：\n- 寄到您家的税表，比如 W-2（工作单位给的）、1099、1098、1095\n- 报税表上每个人的社安卡（Social Security card）或 ITIN 信\n- 您和您爱人带照片的身份证件（比如驾照）\n\n报税表上的信息由您负责，请如实、完整地回答。\n看不懂的问题可以选\"我不确定\"，志愿者会帮您。\n\n如果志愿者有不当行为，请发邮件举报：ts.voltax@irs.gov"}},"questions":[{"id":"form_version","type":"choice","required":false,"options":[{"value":"general","label":{"general":{"en":"No, use the standard version","zh":"否，使用标准版"},"senior":{"en":"No, use the standard version","zh":"不用，用标准版"}}},{"value":"senior","label":{"general":{"en":"Yes, use the senior version","zh":"是，使用长者版"},"senior":{"en":"Yes, use the senior version","zh":"要，用长者版"}}}],"tips":{"general":[{"en":"The senior version asks the same questions, with shorter explanations and easier words. You can switch at any time with the \"Senior version\" switch at the top; your answers are kept.","zh":"长者版的问题与标准版相同，说明更简短，用词更易懂。您可以随时通过页面顶部的\"长者版\"开关切换，已填写的内容会保留。"}],"senior":[{"en":"The senior version asks the same questions. The explanations are shorter and the words are easier. You can change back any time with the \"Senior version\" switch at the top. Your answers will not be lost.","zh":"长者版问的问题一样，只是说明更短、用词更简单。随时可以用页面最上面的\"长者版\"开关换回来，填好的内容不会丢。"}]},"wording":{"general":{"en":"Would you like to use the senior version of this form?","zh":"是否使用长者版表格？"},"senior":{"en":"Do you want to use the senior version of this form?","zh":"您想用长者版的表格吗？"}}},{"id":"service","type":"choice","required":true,"options":[{"value":"same_day","label":{"general":{"en":"Same-day","zh":"当天办理"},"senior":{"en":"Same-day","zh":"当天办理"}}},{"value":"drop_off","label":{"general":{"en":"Drop-off","zh":"送件办理"},"senior":{"en":"Drop-off","zh":"送件办理"}}},{"value":"online","label":{"general":{"en":"Online","zh":"线上办理"},"senior":{"en":"Online","zh":"线上办理"}}}],"wording":{"general":{"en":"How would you like to get tax help?","zh":"您希望以哪种方式获得报税帮助？"},"senior":{"en":"How would you like to get tax help?","zh":"您希望以哪种方式获得报税帮助？"}}},{"id":"language","type":"choice","required":true,"options":[{"value":"english","label":{"general":{"en":"English","zh":"英语"},"senior":{"en":"English","zh":"英语"}}},{"value":"cantonese","label":{"general":{"en":"Cantonese","zh":"粤语"},"senior":{"en":"Cantonese","zh":"粤语"}}},{"value":"mandarin","label":{"general":{"en":"Mandarin","zh":"普通话"},"senior":{"en":"Mandarin","zh":"普通话"}}},{"value":"other","label":{"general":{"en":"Other","zh":"其他"},"senior":{"en":"Other","zh":"其他"}}}],"wording":{"general":{"en":"Preferred service language","zh":"首选服务语言"},"senior":{"en":"Preferred service language","zh":"首选服务语言"}}},{"id":"language_other","type":"text","required":false,"showIf":[{"field":"language","op":"eq","value":"other"}],"wording":{"general":{"en":"Please specify","zh":"请说明"},"senior":{"en":"Please specify","zh":"请说明"}}}]}]},{"n":2,"title":{"en":"About you","zh":"关于您"},"sections":[{"n":1,"title":{"general":{"en":"About You","zh":"个人信息"},"senior":{"en":"About You","zh":"关于您"}},"questions":[{"id":"tp_first_name","type":"text","required":true,"tips":{"general":[{"en":"As shown on your Social Security card.","zh":"请与社会安全卡上的拼写一致。"}],"senior":[{"en":"Write it the same way as on your Social Security card.","zh":"拼写要和社安卡上的一模一样。"}]},"wording":{"general":{"en":"First name","zh":"名"},"senior":{"en":"What is your first name?","zh":"您的名字（名）是什么？请只写\"名\"，不要写\"姓\"。"}}},{"id":"tp_middle_name","type":"text","required":false,"tips":{"general":[{"en":"Leave blank if you don''t have one.","zh":"如没有可留空。"}],"senior":[{"en":"If you don''t have a middle name, leave this empty.","zh":"有就写，没有就空着。"}]},"wording":{"general":{"en":"Middle name","zh":"中间名"},"senior":{"en":"What is your middle name?","zh":"您的中间名是什么？"}}},{"id":"tp_last_name","type":"text","required":true,"tips":{"general":[{"en":"As shown on your Social Security card.","zh":"请与社会安全卡上的拼写一致。"}],"senior":[{"en":"Write it the same way as on your Social Security card.","zh":"拼写要和社安卡上的一模一样。"}]},"wording":{"general":{"en":"Last name","zh":"姓"},"senior":{"en":"What is your last name?","zh":"您的姓是什么？"}}},{"id":"tp_dob","type":"date","required":true,"tips":{"general":[],"senior":[{"en":"Month / Day / Year.","zh":"按 月/日/年 的顺序填写。"}]},"wording":{"general":{"en":"Date of birth","zh":"出生日期"},"senior":{"en":"When were you born?","zh":"您的出生日期是哪一天？"}}},{"id":"tp_job_title","type":"text","required":true,"tips":{"general":[{"en":"For example: cook, cashier, driver, student, retired, unemployed.","zh":"例如：厨师、收银员、司机、学生、退休、无业。"}],"senior":[{"en":"For example: cook, caregiver, delivery driver, student, retired, no job.","zh":"比如：厨师、护工、外卖司机、学生、退休、没有工作。"}]},"wording":{"general":{"en":"Occupation","zh":"职业"},"senior":{"en":"What is your job?","zh":"您做什么工作？"}}},{"id":"tp_phone","type":"phone","required":true,"wording":{"general":{"en":"Phone number","zh":"电话号码"},"senior":{"en":"What is your phone number?","zh":"您的电话号码是多少？"}}},{"id":"email","type":"email","required":false,"wording":{"general":{"en":"Email (optional)","zh":"电子邮箱（选填）"},"senior":{"en":"What is your email? (You can skip this.)","zh":"您的电子邮箱是什么？（可以不填）"}}},{"id":"best_contact_time","type":"multi","required":false,"options":[{"value":"weekday_morning","label":{"general":{"en":"Weekday mornings","zh":"工作日上午"},"senior":{"en":"Weekday mornings","zh":"平时上午"}}},{"value":"weekday_afternoon","label":{"general":{"en":"Weekday afternoons","zh":"工作日下午"},"senior":{"en":"Weekday afternoons","zh":"平时下午"}}},{"value":"weekday_evening","label":{"general":{"en":"Weekday evenings","zh":"工作日晚上"},"senior":{"en":"Weekday evenings","zh":"平时晚上"}}},{"value":"weekend","label":{"general":{"en":"Weekends","zh":"周末"},"senior":{"en":"Weekends","zh":"周末"}}},{"value":"any_time","label":{"general":{"en":"Any time","zh":"任何时间"},"senior":{"en":"Any time is fine","zh":"什么时候都行"}}}],"tips":{"general":[{"en":"Choose all that apply. A volunteer may call you with questions about your return.","zh":"可多选。志愿者可能会就您的报税问题致电联系您。"}],"senior":[{"en":"Pick all the times that work for you. A volunteer may call you with a question.","zh":"可以多选。志愿者可能会打电话问您问题。"}]},"wording":{"general":{"en":"Best time to reach you","zh":"方便联系的时间"},"senior":{"en":"When is a good time for us to call you?","zh":"什么时候给您打电话比较方便？"}}},{"id":"best_contact_note","type":"text","required":false,"tips":{"general":[{"en":"For example: after 6 PM, or text first.","zh":"例如：下午 6 点以后，或请先发短信。"}],"senior":[{"en":"For example: after 6 PM, or call my daughter.","zh":"比如：晚上 6 点以后，或者打给我女儿。"}]},"wording":{"general":{"en":"Notes about reaching you (optional)","zh":"联系备注（选填）"},"senior":{"en":"Anything else we should know? (You can skip this.)","zh":"还有什么要告诉我们的吗？（可以不填）"}}}]},{"n":2,"title":{"general":{"en":"Mailing Address","zh":"邮寄地址"},"senior":{"en":"Your Address","zh":"您的地址"}},"questions":[{"id":"addr_street","type":"text","required":true,"tips":{"general":[{"en":"The address where you receive mail. IRS letters will be sent here.","zh":"请填写您的收信地址，国税局（IRS）的信件会寄到此地址。"}],"senior":[{"en":"This is where you get your mail. Letters from the IRS will be sent here.","zh":"请填您平时收信的地址，国税局（IRS）的信会寄到这里。"}]},"wording":{"general":{"en":"Street address","zh":"街道地址"},"senior":{"en":"What is your street address?","zh":"您收信的地址是什么？（门牌号和街道名）"}}},{"id":"addr_apt","type":"text","required":false,"wording":{"general":{"en":"Apartment number","zh":"公寓号"},"senior":{"en":"Apartment number (if you have one)","zh":"公寓号或房间号（没有就空着）"}}},{"id":"addr_city","type":"text","required":true,"wording":{"general":{"en":"City","zh":"城市"},"senior":{"en":"City","zh":"您住在哪个城市？"}}},{"id":"addr_state","type":"text","required":true,"wording":{"general":{"en":"State","zh":"州"},"senior":{"en":"State","zh":"您住在哪个州？"}}},{"id":"addr_zip","type":"zip","required":true,"wording":{"general":{"en":"ZIP code","zh":"邮编"},"senior":{"en":"ZIP code","zh":"您家的邮编是多少？（5 位数字）"}}}]}]},{"n":3,"title":{"en":"Marriage & spouse","zh":"婚姻与配偶"},"sections":[{"n":3,"title":{"general":{"en":"Marital Status","zh":"婚姻状况"},"senior":{"en":"Marriage","zh":"婚姻状况"}},"questions":[{"id":"marital_status","type":"choice","required":true,"options":[{"value":"never_married","label":{"general":{"en":"Never married","zh":"未婚"},"senior":{"en":"Never married","zh":"从来没结过婚"}}},{"value":"married","label":{"general":{"en":"Married","zh":"已婚"},"senior":{"en":"Married","zh":"已婚"}}},{"value":"divorced","label":{"general":{"en":"Divorced","zh":"离婚"},"senior":{"en":"Divorced","zh":"已离婚"}}},{"value":"separated","label":{"general":{"en":"Legally separated, but not divorced","zh":"法定分居（未离婚）"},"senior":{"en":"Legally separated, but not divorced","zh":"法院判了分居，但还没离婚"}}},{"value":"widowed","label":{"general":{"en":"Widowed","zh":"丧偶"},"senior":{"en":"My husband or wife died","zh":"丧偶（爱人已去世）"}}}],"tips":{"general":[{"en":"\"Legally separated\" means you have a court-issued separation decree. Simply living apart does not count.","zh":"\"法定分居\"指法院已出具分居判决，仅分开居住不算。"}],"senior":[{"en":"\"Legally separated\" means a court gave you a paper saying you are separated. Just living apart is not the same.","zh":"\"法院判了分居\"是指法院给了您一份正式的分居文件。只是平时不住在一起，不算。"}]},"wording":{"general":{"en":"As of December 31, 2025, what was your marital status?","zh":"截至 2025 年 12 月 31 日，您的婚姻状况是？"},"senior":{"en":"On December 31, 2025, were you…","zh":"在 2025 年 12 月 31 日，您的婚姻状况是？"}}},{"id":"married_last_day","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"}],"showIf":[{"field":"marital_status","op":"eq","value":"married"}],"wording":{"general":{"en":"Were you married on the last day of 2025 (December 31)?","zh":"2025 年最后一天（12 月 31 日），您是否仍处于已婚状态？"},"senior":{"en":"Were you still married on the last day of 2025 (December 31)?","zh":"在 2025 年最后一天（12 月 31 日），您和您爱人还是夫妻吗？"}}},{"id":"lived_apart_last_6mo","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"}],"showIf":[{"field":"marital_status","op":"eq","value":"married"}],"wording":{"general":{"en":"Did you and your spouse live apart for all of the last 6 months of 2025 (July 1 – December 31)?","zh":"2025 年最后 6 个月（7 月 1 日至 12 月 31 日），您和配偶是否一直分开居住？"},"senior":{"en":"From July 1 to December 31, 2025, did you and your spouse live in different homes the whole time?","zh":"2025 年 7 月 1 日到 12 月 31 日，您和您爱人是不是一直分开住？"}}},{"id":"divorce_date","type":"date","required":true,"showIf":[{"field":"marital_status","op":"eq","value":"divorced"}],"tips":{"general":[{"en":"Found on your divorce decree.","zh":"见法院离婚判决书。"}],"senior":[{"en":"This date is on your divorce papers from the court.","zh":"请看法院离婚文件上的日期。"}]},"wording":{"general":{"en":"Date of final divorce decree","zh":"离婚判决生效日期"},"senior":{"en":"What date was your divorce made final?","zh":"法院正式判您离婚是哪一天？"}}},{"id":"separation_date","type":"date","required":true,"showIf":[{"field":"marital_status","op":"eq","value":"separated"}],"tips":{"general":[{"en":"Found on your court separation papers.","zh":"见法院分居判决文件。"}],"senior":[{"en":"This date is on your court papers.","zh":"请看法院分居文件上的日期。"}]},"wording":{"general":{"en":"Date of separate maintenance decree","zh":"法定分居判决日期"},"senior":{"en":"What date did the court make your separation official?","zh":"法院正式判您分居是哪一天？"}}},{"id":"spouse_death_year","type":"year","required":true,"showIf":[{"field":"marital_status","op":"eq","value":"widowed"}],"wording":{"general":{"en":"Year of spouse''s death","zh":"配偶去世年份"},"senior":{"en":"What year did your spouse die?","zh":"您爱人是哪一年去世的？"}}}]},{"n":4,"title":{"general":{"en":"Spouse Information","zh":"配偶信息"},"senior":{"en":"About Your Spouse","zh":"关于您爱人"}},"questions":[{"id":"sp_first_name","type":"text","required":true,"showIf":[{"field":"marital_status","op":"eq","value":"married"}],"tips":{"general":[{"en":"As shown on their Social Security card.","zh":"请与社会安全卡上的拼写一致。"}],"senior":[{"en":"Write it the same way as on their Social Security card.","zh":"拼写要和社安卡上的一模一样。"}]},"wording":{"general":{"en":"Spouse''s first name","zh":"配偶的名"},"senior":{"en":"Your spouse''s first name","zh":"您爱人的名字（名）是什么？请只写\"名\"，不要写\"姓\"。"}}},{"id":"sp_middle_name","type":"text","required":false,"showIf":[{"field":"marital_status","op":"eq","value":"married"}],"tips":{"general":[{"en":"Leave blank if your spouse doesn''t have one.","zh":"如没有可留空。"}],"senior":[{"en":"If your spouse doesn''t have a middle name, leave this empty.","zh":"有就写，没有就空着。"}]},"wording":{"general":{"en":"Spouse''s middle name","zh":"配偶的中间名"},"senior":{"en":"Your spouse''s middle name","zh":"您爱人的中间名是什么？"}}},{"id":"sp_last_name","type":"text","required":true,"showIf":[{"field":"marital_status","op":"eq","value":"married"}],"wording":{"general":{"en":"Spouse''s last name","zh":"配偶的姓"},"senior":{"en":"Your spouse''s last name","zh":"您爱人姓什么？"}}},{"id":"sp_dob","type":"date","required":true,"showIf":[{"field":"marital_status","op":"eq","value":"married"}],"wording":{"general":{"en":"Spouse''s date of birth","zh":"配偶出生日期"},"senior":{"en":"Your spouse''s date of birth","zh":"您爱人的出生日期是哪一天？"}}},{"id":"sp_job_title","type":"text","required":true,"showIf":[{"field":"marital_status","op":"eq","value":"married"}],"tips":{"general":[{"en":"For example: cook, cashier, driver, student, retired, unemployed.","zh":"例如：厨师、收银员、司机、学生、退休、无业。"}],"senior":[{"en":"For example: cook, caregiver, delivery driver, student, retired, no job.","zh":"比如：厨师、护工、外卖司机、学生、退休、没有工作。"}]},"wording":{"general":{"en":"Spouse''s occupation","zh":"配偶职业"},"senior":{"en":"Your spouse''s job","zh":"您爱人做什么工作？"}}},{"id":"sp_phone","type":"phone","required":false,"showIf":[{"field":"marital_status","op":"eq","value":"married"}],"wording":{"general":{"en":"Spouse''s phone number","zh":"配偶电话号码"},"senior":{"en":"Your spouse''s phone number","zh":"您爱人的电话号码是多少？"}}}]}]},{"n":4,"title":{"en":"Your 2025 situation","zh":"您 2025 年的情况"},"sections":[{"n":5,"title":{"general":{"en":"Your Situation in 2025","zh":"2025 年基本情况"},"senior":{"en":"Your Situation in 2025","zh":"您 2025 年的情况"}},"questions":[{"id":"multi_state","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"tips":{"general":[{"en":"For example, you live in New York but work in New Jersey.","zh":"例如：住在纽约州，在新泽西州工作。"}],"senior":[{"en":"For example, you live in Pennsylvania but work in New Jersey.","zh":"比如：您住在宾州，但在新泽西州上班。"}]},"wording":{"general":{"en":"Did you live or work in two or more states in 2025?","zh":"2025 年，您是否在两个或以上的州居住或工作过？"},"senior":{"en":"In 2025, did you live or work in 2 or more states?","zh":"2025 年，您有没有在两个或更多的州住过或工作过？"}}},{"id":"claimed_by_other","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"tips":{"general":[{"en":"Common for students still supported by their parents.","zh":"常见于仍由父母供养的学生。"}],"senior":[{"en":"This often happens with students whose parents still support them.","zh":"常见情况：父母还在供养的学生。"}]},"wording":{"general":{"en":"Can anyone else (such as a parent or adult child) claim you or your spouse as a dependent on their tax return?","zh":"是否有其他人（如父母或成年子女）可以在其报税表上将您或配偶列为受抚养人？"},"senior":{"en":"Can someone else (like a parent or grown child) list you or your spouse as a dependent on their tax return?","zh":"有没有别人（比如您的父母或成年子女）报税时，会把您或您爱人写进他们的税表里，算作由他们养活的人？"}}},{"id":"us_citizen","type":"who","required":true,"options":[{"value":"me"},{"value":"spouse"},{"value":"none"}],"wording":{"general":{"en":"Who is a U.S. citizen?","zh":"以下谁是美国公民？"},"senior":{"en":"Who is a U.S. citizen?","zh":"您和您爱人，谁是美国公民？"}}},{"id":"on_visa","type":"who","required":true,"options":[{"value":"me"},{"value":"spouse"},{"value":"none"}],"tips":{"general":[{"en":"For example, a student or work visa. A green card is **not** a visa.","zh":"例如学生签证、工作签证。**绿卡不属于签证。**"}],"senior":[{"en":"For example, a student visa or work visa. A green card is **NOT** a visa.","zh":"比如学生签证、工作签证。**有绿卡不算签证，请不要选。**"}]},"wording":{"general":{"en":"Who was in the U.S. on a visa in 2025?","zh":"2025 年，以下谁持签证在美国？"},"senior":{"en":"Who was in the U.S. on a visa in 2025?","zh":"2025 年，您和您爱人，谁是拿签证待在美国的？"}}},{"id":"fulltime_student","type":"who","required":true,"options":[{"value":"me"},{"value":"spouse"},{"value":"none"}],"tips":{"general":[{"en":"Enrolled full-time, as defined by the school, for at least 5 months of the year.","zh":"指全年至少有 5 个月被学校认定为全日制在读。"}],"senior":[]},"wording":{"general":{"en":"Who was a full-time student in 2025?","zh":"2025 年，以下谁是全日制学生？"},"senior":{"en":"Who was a full-time student in 2025?","zh":"2025 年，您和您爱人，谁至少有 5 个月是学校认定的全日制学生？"}}},{"id":"legally_blind","type":"who","required":true,"options":[{"value":"me"},{"value":"spouse"},{"value":"none"}],"tips":{"general":[{"en":"Certified by a doctor; vision cannot be adequately corrected with glasses.","zh":"需有医生证明，戴眼镜也无法充分矫正视力。"}],"senior":[{"en":"A doctor said you cannot see well even with glasses.","zh":"意思是：医生证明戴眼镜也看不清楚。"}]},"wording":{"general":{"en":"Who is legally blind?","zh":"以下谁属于法定失明？"},"senior":{"en":"Who is legally blind?","zh":"您和您爱人，谁有医生证明是法定失明？"}}},{"id":"disabled","type":"who","required":true,"options":[{"value":"me"},{"value":"spouse"},{"value":"none"}],"tips":{"general":[{"en":"Certified by a doctor as unable to work due to a condition expected to last at least 1 year or be permanent.","zh":"需有医生证明，因健康原因无法工作，且预计持续至少 1 年或永久。"}],"senior":[{"en":"A doctor said you cannot work because of a health problem that will last at least 1 year or forever.","zh":"意思是：医生证明因为身体问题不能工作，而且至少会持续一年或一辈子。"}]},"wording":{"general":{"en":"Who is totally and permanently disabled?","zh":"以下谁属于完全且永久性残疾？"},"senior":{"en":"Who is totally and permanently disabled?","zh":"您和您爱人，谁是完全并且永久残疾？"}}},{"id":"ippin","type":"who","required":true,"options":[{"value":"me"},{"value":"spouse"},{"value":"none"}],"tips":{"general":[{"en":"A 6-digit number from the IRS, issued after identity theft or through voluntary sign-up. A new one is issued every year. If you have one, upload this year''s letter.","zh":"国税局发放的 6 位数字，通常在身份被盗用后发放，也可自行申请，**每年更换**。如有，请上传今年的通知信。"}],"senior":[{"en":"The IRS sends a new one each year, often after identity theft. You may also have signed up for it yourself. If you have one, please upload this year''s letter.","zh":"这个号码通常是身份被盗用后国税局寄来的，也可能是您自己申请的，**每年都会换一个新的**。如果有，请上传今年收到的那封信。"}]},"wording":{"general":{"en":"Who was issued an Identity Protection PIN (IP PIN)?","zh":"以下谁持有国税局（IRS）发放的身份保护码（IP PIN）？"},"senior":{"en":"Who got an Identity Protection PIN (IP PIN) from the IRS?","zh":"您和您爱人，谁收到过国税局（IRS）寄来的 6 位数字号码，叫\"身份保护码\"（IP PIN）？"}}},{"id":"digital_assets","type":"who","required":true,"options":[{"value":"me"},{"value":"spouse"},{"value":"none"}],"wording":{"general":{"en":"Who owned or held any digital assets (such as Bitcoin, Ethereum, or other cryptocurrency) in 2025?","zh":"2025 年，以下谁拥有或持有数字资产（如比特币、以太坊等加密货币）？"},"senior":{"en":"Who owned or held any digital money (like Bitcoin or other crypto) in 2025?","zh":"2025 年，您和您爱人，谁拥有过数字货币（比如比特币、以太坊、狗狗币）？"}}}]}]},{"n":5,"title":{"en":"Household","zh":"家庭成员"},"sections":[{"n":6,"title":{"general":{"en":"Household Members and Dependents","zh":"家庭成员及受抚养人"},"senior":{"en":"People Who Live With You or That You Support","zh":"和您同住的人，或您出钱养的人"}},"intro":{"general":{"en":"List **everyone who lived with you in 2025** (except your spouse), and **anyone you financially supported** who did not live with you.","zh":"请列出 2025 年与您同住的所有人（配偶除外），以及未与您同住但由您提供经济支持的人。"},"senior":{"en":"Tell us about **everyone who lived with you in 2025** (not your spouse).\nAlso tell us about **anyone you gave money to for living costs**, even if they did not live with you.\nFor example: your children, your parents, other family members.","zh":"请告诉我们 2025 年和您住在一起的所有人（您爱人除外），以及虽然不住在一起、但您出钱养的人。\n比如：您的孩子、父母、其他家人。"}},"questions":[{"id":"has_household_members","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"}],"wording":{"general":{"en":"Did anyone live with you or receive financial support from you in 2025?","zh":"2025 年，是否有人与您同住或由您提供经济支持？"},"senior":{"en":"Did anyone live with you or depend on you for money in 2025?","zh":"2025 年，有没有人和您住在一起，或者靠您出钱生活？"}}},{"id":"hh","type":"group","required":true,"showIf":[{"field":"has_household_members","op":"eq","value":"yes"}],"fields":[{"id":"first_name","type":"text","required":true,"wording":{"general":{"en":"First name","zh":"名"},"senior":{"en":"First name","zh":"这个人的名字（名）"}}},{"id":"last_name","type":"text","required":true,"wording":{"general":{"en":"Last name","zh":"姓"},"senior":{"en":"Last name","zh":"这个人的姓"}}},{"id":"dob","type":"date","required":true,"wording":{"general":{"en":"Date of birth","zh":"出生日期"},"senior":{"en":"Date of birth","zh":"这个人的出生日期"}}},{"id":"relationship","type":"choice","required":true,"options":[{"value":"son_daughter","label":{"general":{"en":"Son / Daughter","zh":"子女"},"senior":{"en":"Son / Daughter","zh":"儿子/女儿"}}},{"value":"stepchild","label":{"general":{"en":"Stepchild","zh":"继子女"},"senior":{"en":"Stepchild","zh":"继子女"}}},{"value":"foster_child","label":{"general":{"en":"Foster child","zh":"寄养子女"},"senior":{"en":"Foster child","zh":"寄养的孩子"}}},{"value":"grandchild","label":{"general":{"en":"Grandchild","zh":"孙子女/外孙子女"},"senior":{"en":"Grandchild","zh":"孙子女/外孙子女"}}},{"value":"sibling","label":{"general":{"en":"Brother / Sister","zh":"兄弟姐妹"},"senior":{"en":"Brother / Sister","zh":"兄弟姐妹"}}},{"value":"niece_nephew","label":{"general":{"en":"Niece / Nephew","zh":"侄子女/外甥子女"},"senior":{"en":"Niece / Nephew","zh":"侄子女/外甥子女"}}},{"value":"parent","label":{"general":{"en":"Parent","zh":"父母"},"senior":{"en":"Parent","zh":"父母"}}},{"value":"grandparent","label":{"general":{"en":"Grandparent","zh":"祖父母/外祖父母"},"senior":{"en":"Grandparent","zh":"祖父母/外祖父母"}}},{"value":"other_relative","label":{"general":{"en":"Other relative","zh":"其他亲属"},"senior":{"en":"Other relative","zh":"其他亲戚"}}},{"value":"none","label":{"general":{"en":"None","zh":"无亲属关系"},"senior":{"en":"Not related","zh":"不是亲戚"}}}],"wording":{"general":{"en":"Relationship to you","zh":"与您的关系"},"senior":{"en":"How is this person related to you?","zh":"这个人和您是什么关系？"}}},{"id":"months_lived","type":"number","required":true,"min":0,"max":12,"tips":{"general":[{"en":"If born in 2025 and lived with you since birth, enter 12.","zh":"如 2025 年出生且出生后一直与您同住，请填 12。"}],"senior":[{"en":"If they were born in 2025 and lived with you since birth, choose 12.","zh":"如果是 2025 年出生、一出生就和您住在一起，请选 12。"}]},"wording":{"general":{"en":"Number of months lived in your home in 2025","zh":"2025 年在您家居住的月数"},"senior":{"en":"How many months did this person live in your home in 2025?","zh":"2025 年，这个人在您家住了几个月？"}}},{"id":"married","type":"choice","required":true,"options":[{"value":"married","label":{"general":{"en":"Married","zh":"已婚"},"senior":{"en":"Yes (Married)","zh":"已婚"}}},{"value":"single","label":{"general":{"en":"Single","zh":"未婚"},"senior":{"en":"No (Single)","zh":"未婚"}}}],"wording":{"general":{"en":"Marital status as of December 31, 2025","zh":"截至 2025 年 12 月 31 日的婚姻状况"},"senior":{"en":"Was this person married on December 31, 2025?","zh":"在 2025 年 12 月 31 日，这个人结婚了吗？"}}},{"id":"us_citizen","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"wording":{"general":{"en":"U.S. citizen?","zh":"是否为美国公民？"},"senior":{"en":"Is this person a U.S. citizen?","zh":"这个人是美国公民吗？"}}},{"id":"resident_na","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"wording":{"general":{"en":"In 2025, was this person a resident of the U.S., Canada, or Mexico?","zh":"2025 年，此人是否居住在美国、加拿大或墨西哥？"},"senior":{"en":"In 2025, did this person live in the U.S., Canada, or Mexico?","zh":"2025 年，这个人是住在美国、加拿大或墨西哥吗？"}}},{"id":"fulltime_student","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"wording":{"general":{"en":"Full-time student in 2025 (at least 5 months)?","zh":"2025 年是否为全日制学生（至少 5 个月）？"},"senior":{"en":"Was this person a full-time student in 2025?","zh":"2025 年，这个人有没有至少 5 个月是学校认定的全日制学生？"}}},{"id":"disabled","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"wording":{"general":{"en":"Totally and permanently disabled?","zh":"是否为完全且永久性残疾？"},"senior":{"en":"Is this person totally and permanently disabled?","zh":"这个人是完全并且永久残疾吗？"}}},{"id":"ippin","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"tips":{"general":[{"en":"If yes, upload this year''s letter.","zh":"如有，请上传今年的通知信。"}],"senior":[{"en":"If yes, please upload this year''s letter.","zh":"如果有，请上传今年收到的那封信。"}]},"wording":{"general":{"en":"Issued an IP PIN?","zh":"是否持有身份保护码（IP PIN）？"},"senior":{"en":"Did this person get an IP PIN from the IRS?","zh":"这个人有没有收到过国税局寄来的 6 位数字\"身份保护码\"（IP PIN）？"}}}],"wording":{"general":{"en":"People in your household","zh":"家庭成员"},"senior":{"en":"People in your household","zh":"家庭成员"}}}]}]},{"n":6,"title":{"en":"Income","zh":"收入"},"sections":[{"n":9,"title":{"general":{"en":"Income in 2025","zh":"2025 年收入"},"senior":{"en":"Money You Got in 2025 (Income)","zh":"您 2025 年收到的钱（收入）"}},"intro":{"general":{"en":"Did **you or your spouse** receive any of the following in 2025? If yes, please upload the related tax forms.","zh":"2025 年，您或配偶是否有以下收入？如有，请上传相关税表。"},"senior":{"en":"For each item below: did **you or your spouse** get this kind of money in 2025? If yes, please upload the tax papers for it.","zh":"下面每一题都在问：2025 年，您或您爱人有没有收到过这种钱？如果有，请上传相关的税表。"}},"questions":[{"id":"inc_wages","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"tips":{"general":[{"en":"Reported on Form **W-2**.","zh":"对应 **W-2** 表。"}],"senior":[{"en":"You usually get a **W-2** form from your employer.","zh":"一般会从工作单位收到 **W-2** 表。"}]},"wording":{"general":{"en":"Wages from a part-time or full-time job","zh":"工资（兼职或全职）"},"senior":{"en":"Pay from a job (part-time or full-time)","zh":"上班的工资（兼职或全职）"}}},{"id":"inc_wages_job_count","type":"number","required":false,"showIf":[{"field":"inc_wages","op":"eq","value":"yes"}],"tips":{"general":[{"en":"Usually one W-2 per job.","zh":"通常一份工作对应一张 W-2。"}],"senior":[{"en":"Usually one W-2 for each job.","zh":"一般一份工作一张 W-2，有几张 W-2 就填几。"}]},"wording":{"general":{"en":"How many jobs did you and your spouse have in 2025?","zh":"2025 年您和配偶共有几份工作？"},"senior":{"en":"How many jobs did you and your spouse have in 2025?","zh":"2025 年，您和您爱人一共做了几份工作？"}}},{"id":"inc_tips","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"tips":{"general":[{"en":"All tips, including cash tips, are income. Some tips may be deductible starting in 2025; please have your tip records ready.","zh":"所有小费（含现金小费）均需申报。自 2025 年起部分小费可能可以扣除，请准备好小费记录，志愿者会协助判断。"}],"senior":[{"en":"All tips count as income, including cash tips. Some tips may lower your tax starting in 2025. Please bring your tip records, and the volunteer will check.","zh":"所有小费都要报，包括现金小费。从 2025 年起，部分小费可能可以减税。请准备好您记录的小费金额，志愿者会帮您判断。"}]},"wording":{"general":{"en":"Tips","zh":"小费"},"senior":{"en":"Tips (extra money from customers)","zh":"小费（客人额外给的钱）"}}},{"id":"inc_retirement","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"tips":{"general":[{"en":"Such as a 401(k) or IRA. Reported on Form **1099-R**.","zh":"如 401(k)、IRA，对应 **1099-R** 表。"}],"senior":[{"en":"Like a 401(k) or IRA. You usually get a **1099-R** form.","zh":"比如 401(k) 或 IRA。一般会收到 **1099-R** 表。"}]},"wording":{"general":{"en":"Retirement account, pension, or annuity distributions","zh":"退休账户、养老金或年金收入"},"senior":{"en":"Money from a retirement account, pension, or annuity","zh":"从退休账户、养老金或年金拿到的钱"}}},{"id":"inc_disability","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"wording":{"general":{"en":"Disability benefits (from insurance or workers'' compensation)","zh":"残障补助（保险或工伤赔偿）"},"senior":{"en":"Disability payments (from insurance or workers'' compensation)","zh":"残障补助（保险公司给的，或工伤赔偿）"}}},{"id":"inc_social_security","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"tips":{"general":[{"en":"Reported on Form **SSA-1099** or **RRB-1099**.","zh":"对应 **SSA-1099** 或 **RRB-1099** 表。"}],"senior":[{"en":"You get an **SSA-1099** or **RRB-1099** form.","zh":"会收到 **SSA-1099** 或 **RRB-1099** 表。"}]},"wording":{"general":{"en":"Social Security or Railroad Retirement benefits","zh":"社会安全金或铁路退休金"},"senior":{"en":"Social Security or Railroad Retirement money","zh":"社安金（Social Security）或铁路退休金"}}},{"id":"inc_unemployment","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"tips":{"general":[{"en":"Reported on Form **1099-G**.","zh":"对应 **1099-G** 表。"}],"senior":[{"en":"You get a **1099-G** form.","zh":"会收到 **1099-G** 表。"}]},"wording":{"general":{"en":"Unemployment benefits","zh":"失业金"},"senior":{"en":"Unemployment money","zh":"失业金"}}},{"id":"inc_state_refund","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"tips":{"general":[],"senior":[{"en":"Money your state or city gave back to you from last year''s taxes.","zh":"就是州政府或市政府退给您的去年的税。"}]},"wording":{"general":{"en":"Refund of state or local income tax","zh":"州或地方所得税退税"},"senior":{"en":"A refund of state or local income tax","zh":"州税或市税的退税"}}},{"id":"inc_interest_div","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"tips":{"general":[{"en":"Reported on Form **1099-INT** or **1099-DIV**.","zh":"对应 **1099-INT** 或 **1099-DIV** 表。"}],"senior":[{"en":"You get a **1099-INT** or **1099-DIV** form.","zh":"会收到 **1099-INT** 或 **1099-DIV** 表。"}]},"wording":{"general":{"en":"Interest or dividends (bank accounts, bonds, stocks, etc.)","zh":"利息或股息（银行账户、债券、股票等）"},"senior":{"en":"Interest or dividends (from a bank account, bonds, stocks, etc.)","zh":"银行利息或股票分红（银行账户、债券、股票等）"}}},{"id":"inc_sale_assets","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"tips":{"general":[{"en":"Reported on Form **1099-B**. Please also upload your brokerage statement.","zh":"对应 **1099-B** 表，请同时上传券商对账单。"}],"senior":[{"en":"You usually get a **1099-B** form. Please upload your broker statement too.","zh":"一般会收到 **1099-B** 表。请把证券公司的对账单也一起上传。"}]},"wording":{"general":{"en":"Sale of stocks, bonds, or real estate","zh":"出售股票、债券或房地产"},"senior":{"en":"You sold stocks, bonds, or real estate (land or buildings)","zh":"卖了股票、债券或房地产（房子、土地）"}}},{"id":"inc_sale_assets_prior_loss","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"showIf":[{"field":"inc_sale_assets","op":"eq","value":"yes"}],"wording":{"general":{"en":"Did you report a loss from these sales on last year''s return?","zh":"去年的报税表是否申报过此类亏损？"},"senior":{"en":"Did last year''s tax return show a loss from selling these?","zh":"去年的报税表上，有没有这类买卖亏钱的记录？"}}},{"id":"inc_alimony","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"wording":{"general":{"en":"Alimony received (not child support)","zh":"收到的赡养费（不含子女抚养费）"},"senior":{"en":"Alimony (money from a former spouse, NOT child support)","zh":"赡养费（前夫或前妻给您的钱，**不包括**孩子的抚养费）"}}},{"id":"inc_rental_home","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"wording":{"general":{"en":"Income from renting out your house or a room in your house","zh":"出租房屋或房间的收入"},"senior":{"en":"You rented out your house or a room in your house","zh":"把您的房子或房间租给别人"}}},{"id":"inc_rental_home_under15","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"showIf":[{"field":"inc_rental_home","op":"eq","value":"yes"}],"wording":{"general":{"en":"Did you also use it as your home AND rent it out for fewer than 15 days in 2025?","zh":"该房屋是否同时为您的自住房，且 2025 年出租不足 15 天？"},"senior":{"en":"Did you also live in that home, AND rent it out for less than 15 days in 2025?","zh":"这个房子您自己也住，而且 2025 年一共租出去不到 15 天吗？"}}},{"id":"inc_rental_property","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"wording":{"general":{"en":"Income from renting out personal property (such as a vehicle or tools)","zh":"出租个人物品（如车辆、工具）的收入"},"senior":{"en":"You rented out your things (like a car)","zh":"把您的东西租给别人（比如汽车、工具）"}}},{"id":"inc_gambling","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"tips":{"general":[{"en":"May be reported on Form **W-2G**.","zh":"可能对应 **W-2G** 表。"}],"senior":[{"en":"You may get a **W-2G** form.","zh":"可能会收到 **W-2G** 表。"}]},"wording":{"general":{"en":"Gambling or lottery winnings","zh":"赌博或彩票奖金"},"senior":{"en":"Gambling or lottery winnings","zh":"赌博赢的钱或彩票中奖"}}},{"id":"inc_self_employed","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"tips":{"general":[{"en":"For example: delivery or rideshare apps, cleaning, selling goods. May be reported on Form **1099-NEC**, **1099-MISC**, or **1099-K**.","zh":"例如：外卖或网约车平台、清洁服务、销售商品。可能对应 **1099-NEC**、**1099-MISC** 或 **1099-K** 表。"}],"senior":[{"en":"For example: delivery or rideshare apps, cleaning houses, selling things. You may get a **1099-NEC**, **1099-MISC**, or **1099-K** form.","zh":"比如：送外卖、开 Uber/Lyft、帮人打扫、卖东西。可能会收到 **1099-NEC**、**1099-MISC** 或 **1099-K** 表。"}]},"wording":{"general":{"en":"Income from contract or self-employment work","zh":"合同工或自雇收入"},"senior":{"en":"Money from contract work or your own business (self-employed)","zh":"打零工、合同工或自己做生意的收入"}}},{"id":"inc_self_employed_prior_loss","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"showIf":[{"field":"inc_self_employed","op":"eq","value":"yes"}],"wording":{"general":{"en":"Did you report a loss from this work on last year''s return?","zh":"去年的报税表是否申报过此项亏损？"},"senior":{"en":"Did last year''s tax return show a loss from this work?","zh":"去年的报税表上，这份工作有没有亏钱的记录？"}}},{"id":"inc_other","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"wording":{"general":{"en":"Any other income? (Cash payments, jury duty, prizes or awards, digital assets, royalties, union strike benefits, etc.)","zh":"其他收入？（如现金收入、陪审员报酬、奖品或奖励、数字资产、版税、工会罢工补助等）"},"senior":{"en":"Any other money? (Cash payments, jury duty, prizes, digital money, royalties, union strike pay, etc.)","zh":"还有其他收入吗？（比如：现金收入、做陪审员的钱、中奖或比赛奖金、数字货币、版税、工会罢工补助）"}}},{"id":"inc_other_desc","type":"text","required":false,"showIf":[{"field":"inc_other","op":"eq","value":"yes"}],"wording":{"general":{"en":"Please describe","zh":"请说明收入类型"},"senior":{"en":"Please tell us what kind of money","zh":"请说明是什么收入"}}}]}]},{"n":7,"title":{"en":"Expenses & events","zh":"支出与事项"},"sections":[{"n":10,"title":{"general":{"en":"Expenses in 2025","zh":"2025 年支出"},"senior":{"en":"Money You Spent in 2025 (Expenses)","zh":"您 2025 年花的钱（开销）"}},"questions":[{"id":"exp_mortgage_interest","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"heading":{"general":{"en":"Part A: Itemized Deduction Expenses","zh":"可分项扣除的支出"},"senior":{"en":"Part A: Big Expenses (these may lower your tax)","zh":"第一部分：大笔开销（可能可以减税）"}},"tips":{"general":[{"en":"Reported on Form **1098**.","zh":"对应 **1098** 表。"}],"senior":[{"en":"You get a **1098** form from your bank.","zh":"银行会寄 **1098** 表给您。"}]},"wording":{"general":{"en":"Mortgage interest","zh":"房贷利息"},"senior":{"en":"Interest on a home loan (mortgage)","zh":"房贷利息"}}},{"id":"exp_taxes","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"wording":{"general":{"en":"Taxes paid: state, local, real estate, sales, etc.","zh":"已缴税款：州税、地方税、房产税、销售税等"},"senior":{"en":"Taxes you paid: state, local, property (real estate), sales tax, etc.","zh":"您交过的税：州税、地方税、房产税、消费税等"}}},{"id":"exp_medical","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"wording":{"general":{"en":"Medical, dental, or prescription expenses","zh":"医疗、牙科或处方药费用"},"senior":{"en":"Medical, dental, or medicine costs","zh":"看病、看牙或买药的钱"}}},{"id":"exp_charity","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"wording":{"general":{"en":"Charitable contributions","zh":"慈善捐款"},"senior":{"en":"Gifts to church or charity","zh":"捐给教会或慈善机构的钱或东西"}}},{"id":"exp_student_loan","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"heading":{"general":{"en":"Part B: Other Expenses","zh":"其他支出"},"senior":{"en":"Part B: Other Expenses","zh":"第二部分：其他开销"}},"tips":{"general":[{"en":"Reported on Form **1098-E**.","zh":"对应 **1098-E** 表。"}],"senior":[{"en":"You get a **1098-E** form.","zh":"会收到 **1098-E** 表。"}]},"wording":{"general":{"en":"Student loan interest","zh":"学生贷款利息"},"senior":{"en":"Interest on a student loan","zh":"学生贷款的利息"}}},{"id":"exp_dependent_care","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"tips":{"general":[{"en":"Have the provider''s name, address, and tax ID number ready.","zh":"请准备好照护机构或人员的名称、地址和税号。"}],"senior":[{"en":"Please have the care provider''s name, address, and tax ID number.","zh":"请准备好托儿所或照顾者的名字、地址和税号。"}]},"wording":{"general":{"en":"Child and dependent care (so you could work)","zh":"为工作而支付的子女或受抚养人照护费用"},"senior":{"en":"Child care or care for a family member so you could work","zh":"为了去上班，付钱请人照顾孩子或家人"}}},{"id":"exp_retirement_contrib","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"wording":{"general":{"en":"Contributions to a retirement account (IRA, 401(k), etc.)","zh":"退休账户供款（IRA、401(k) 等）"},"senior":{"en":"Money you put into a retirement account (IRA, 401(k), etc.)","zh":"存进退休账户的钱（IRA、401(k) 等）"}}},{"id":"exp_educator","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"wording":{"general":{"en":"Classroom supplies purchased as a teacher, teacher''s aide, or other educator","zh":"教师、助教或其他教育工作者自费购买的教学用品"},"senior":{"en":"School supplies you bought as a teacher, teacher''s aide, or other school worker","zh":"您是老师、助教或其他学校员工，自己掏钱买的教学用品"}}},{"id":"exp_alimony_paid","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"tips":{"general":[{"en":"Have your former spouse''s Social Security number ready.","zh":"请准备好前配偶的社会安全号码。"}],"senior":[{"en":"Please have your former spouse''s Social Security number.","zh":"请准备好前夫或前妻的社安号码。"}]},"wording":{"general":{"en":"Alimony paid (not child support)","zh":"支付的赡养费（不含子女抚养费）"},"senior":{"en":"Alimony you paid (NOT child support)","zh":"您付给前夫或前妻的赡养费（**不包括**孩子的抚养费）"}}}]},{"n":11,"title":{"general":{"en":"Tax-Related Events in 2025","zh":"2025 年税务相关事项"},"senior":{"en":"Things That Happened in 2025","zh":"2025 年发生的事"}},"questions":[{"id":"evt_education","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"tips":{"general":[{"en":"Upload Form **1098-T** and payment receipts.","zh":"请上传 **1098-T** 表及缴费收据。"}],"senior":[{"en":"Upload the **1098-T** form from the school, plus payment receipts.","zh":"请上传学校的 **1098-T** 表和交学费的收据。"}]},"wording":{"general":{"en":"You or a family member took classes (college, trade school, job-related training, etc.)","zh":"您或家人参加过课程（大学、职业学校、职业培训等）"},"senior":{"en":"You or someone in your family took classes (college, trade school, job training, etc.)","zh":"您或家人上过课（大学、职业学校、工作培训等）"}}},{"id":"evt_sold_home","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"wording":{"general":{"en":"Sold a home","zh":"出售房屋"},"senior":{"en":"You sold a home","zh":"您卖了房子"}}},{"id":"evt_hsa","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"tips":{"general":[],"senior":[{"en":"A special bank account used only for medical costs.","zh":"这是一种专门用来付医疗费的账户。"}]},"wording":{"general":{"en":"Had a Health Savings Account (HSA)","zh":"持有健康储蓄账户（HSA）"},"senior":{"en":"You had a Health Savings Account (HSA)","zh":"您有健康储蓄账户（HSA）"}}},{"id":"evt_marketplace","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"tips":{"general":[{"en":"Upload every Form **1095-A** you received. Medicaid and Medicare do not count.","zh":"请上传收到的所有 **1095-A** 表。Medicaid 和 Medicare 不属于此类。"}],"senior":[{"en":"Upload every **1095-A** form you got. Medicaid and Medicare do NOT count.","zh":"请上传收到的所有 **1095-A** 表。白卡（Medicaid）和红蓝卡（Medicare）不算。"}]},"wording":{"general":{"en":"Purchased health insurance through the Marketplace (HealthCare.gov or a state exchange)","zh":"通过医保交易市场（HealthCare.gov 或州交易平台）购买医疗保险"},"senior":{"en":"You bought health insurance from the Marketplace (HealthCare.gov or your state''s site)","zh":"2025 年，您有没有在政府医保网站上买医疗保险（HealthCare.gov 或州政府的网站，俗称\"奥巴马保险\"）？"}}},{"id":"evt_energy","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"wording":{"general":{"en":"Purchased and installed energy-efficient home improvements (windows, furnace, insulation, etc.)","zh":"购买并安装节能家居改造（窗户、暖气炉、隔热材料等）"},"senior":{"en":"You bought and installed energy-saving items for your home (windows, furnace, insulation, etc.)","zh":"您买了并安装了节能的家居设备（窗户、暖气炉、隔热材料等）"}}},{"id":"evt_other","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"wording":{"general":{"en":"Other (for example: purchased a new vehicle)","zh":"其他（例如购买新车）"},"senior":{"en":"Other (for example: bought a new car)","zh":"其他事情（比如买了新车）"}}},{"id":"evt_other_desc","type":"text","required":false,"showIf":[{"field":"evt_other","op":"eq","value":"yes"}],"tips":{"general":[{"en":"If you bought a new vehicle with a loan, provide the 17-character VIN (on the purchase contract or registration).","zh":"如贷款购买新车，请提供 17 位车辆识别号（VIN），可在购车合同或车辆登记证上找到。"}],"senior":[{"en":"If you bought a new car with a loan, please give us the VIN (the car''s 17-digit ID number).","zh":"如果您是贷款买的新车，请提供车辆识别号码（VIN，17 位），在购车合同或车辆登记卡上可以找到。"}]},"wording":{"general":{"en":"Please describe","zh":"请说明"},"senior":{"en":"Please tell us what happened","zh":"请说明发生了什么"}}},{"id":"evt_debt_canceled","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"tips":{"general":[{"en":"May be reported on Form **1099-C** or **1099-A**.","zh":"可能对应 **1099-C** 或 **1099-A** 表。"}],"senior":[{"en":"You may get a **1099-C** or **1099-A** form.","zh":"可能会收到 **1099-C** 或 **1099-A** 表。"}]},"wording":{"general":{"en":"Had credit card, mortgage, or other debt canceled or forgiven by a lender","zh":"信用卡、房贷或其他债务被贷款方取消或免除"},"senior":{"en":"A lender forgave or canceled some of your debt (credit card, home loan, etc.)","zh":"银行或贷款公司有没有免掉您欠的一部分或全部钱，您不用再还了？（比如信用卡欠款和解、房子被银行收回）"}}},{"id":"evt_disaster","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"wording":{"general":{"en":"Had a loss in a federally declared disaster area","zh":"在联邦宣布的灾区遭受损失"},"senior":{"en":"You lost property or money because of a disaster the government declared (flood, hurricane, fire, etc.)","zh":"因为政府宣布的灾害（洪水、飓风、火灾等）损失了财产或钱"}}},{"id":"evt_credit_disallowed","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"wording":{"general":{"en":"Had a tax credit disallowed in a prior year (e.g., EITC, Child Tax Credit, American Opportunity Credit)","zh":"以往年度是否有税收抵免被拒（如劳动所得抵免 EITC、儿童税收抵免 CTC、美国机会教育抵免 AOTC）"},"senior":{"en":"In the past, did the IRS say no to a tax credit you asked for? (like Earned Income Credit, Child Tax Credit, or American Opportunity Credit)","zh":"以前国税局有没有拒绝过您申请的税务补助？（比如低收入补助 EITC、儿童税务补助 CTC、大学学费补助 AOTC）"}}},{"id":"evt_irs_letter","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"tips":{"general":[{"en":"Please upload the letter.","zh":"请上传该信件。"}],"senior":[{"en":"Please upload the letter.","zh":"如果有，请上传。"}]},"wording":{"general":{"en":"Received any letter or bill from the IRS","zh":"收到国税局的信件或账单"},"senior":{"en":"Did you get any letter or bill from the IRS?","zh":"您有没有收到过国税局的信或账单？"}}},{"id":"evt_estimated_payments","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"},{"value":"not_sure"}],"wording":{"general":{"en":"Made estimated tax payments or applied last year''s refund to 2025 taxes","zh":"缴纳过预估税，或将去年的退税用于抵缴 2025 年税款"},"senior":{"en":"Did you pay tax early during the year (estimated tax), or put last year''s refund toward 2025 taxes?","zh":"2025 年，您有没有提前预交过税，或者把去年的退税留着抵 2025 年的税？"}}},{"id":"evt_brought_prior_return","type":"yesno","required":true,"options":[{"value":"yes"},{"value":"no"}],"wording":{"general":{"en":"Can you upload last year''s tax return?","zh":"能否上传去年的报税表？"},"senior":{"en":"Can you upload last year''s tax return?","zh":"您能上传去年的报税表吗？"}}}]}]},{"n":8,"title":{"en":"Refund & preferences","zh":"退税与偏好"},"sections":[{"n":7,"title":{"general":{"en":"Refund and Payment","zh":"退税与补税"},"senior":{"en":"Your Refund or Payment","zh":"退税或补税"}},"questions":[{"id":"refund_method","type":"choice","required":true,"options":[{"value":"direct_deposit","label":{"general":{"en":"Direct deposit","zh":"直接存入银行账户（最快）"},"senior":{"en":"Put it straight into my bank account","zh":"直接存进我的银行账户（最快）"}}},{"value":"check","label":{"general":{"en":"Check by mail","zh":"邮寄支票"},"senior":{"en":"Mail me a paper check","zh":"寄一张支票给我"}}},{"value":"split","label":{"general":{"en":"Split between accounts","zh":"分存多个账户"},"senior":{"en":"Split it into more than one bank account","zh":"分开存进几个银行账户"}}},{"value":"other","label":{"general":{"en":"Other","zh":"其他"},"senior":{"en":"Other","zh":"其他方法"}}}],"tips":{"general":[{"showIf":[{"field":"refund_method","op":"ne","value":"check"},{"field":"refund_method","op":"ne","value":"other"}],"en":"Have your bank routing and account numbers ready.","zh":"请准备好银行路由号码和账户号码。"}],"senior":[{"showIf":[{"field":"refund_method","op":"ne","value":"check"},{"field":"refund_method","op":"ne","value":"other"}],"en":"Please have your bank routing number and account number ready. A blank check works.","zh":"请准备好银行的路由号码和账户号码，一张空白支票上就有。"}]},"wording":{"general":{"en":"If you are due a refund, how would you like to receive it?","zh":"如有退税，您希望以何种方式收取？"},"senior":{"en":"If you get money back (a refund), how do you want to get it?","zh":"如果报完税，国税局要退钱给您，您想怎么收到这笔钱？"}}},{"id":"refund_method_other","type":"text","required":false,"showIf":[{"field":"refund_method","op":"eq","value":"other"}],"wording":{"general":{"en":"Please specify","zh":"请说明"},"senior":{"en":"Please tell us more","zh":"请告诉我们您想用什么方法收钱"}}},{"id":"payment_method","type":"choice","required":true,"options":[{"value":"bank_account","label":{"general":{"en":"Bank account (direct debit)","zh":"从银行账户扣款"},"senior":{"en":"Take it from my bank account","zh":"直接从我的银行账户扣"}}},{"value":"direct_pay","label":{"general":{"en":"IRS.gov Direct Pay","zh":"通过国税局网站（IRS.gov Direct Pay）自行付款"},"senior":{"en":"I will pay online at IRS.gov (Direct Pay)","zh":"我自己上国税局网站（IRS.gov）付"}}},{"value":"installment","label":{"general":{"en":"Installment agreement","zh":"申请分期付款"},"senior":{"en":"Pay a little each month (payment plan)","zh":"每个月付一点，分期付完"}}},{"value":"mail","label":{"general":{"en":"Mail payment to the IRS","zh":"邮寄付款给国税局"},"senior":{"en":"Mail a payment to the IRS","zh":"寄支票给国税局"}}}],"wording":{"general":{"en":"If you have a balance due, how would you like to pay?","zh":"如需补税，您希望以何种方式付款？"},"senior":{"en":"If you owe money, how do you want to pay?","zh":"如果报完税发现您还要补交钱，您想怎么付？"}}}]},{"n":8,"title":{"general":{"en":"Language and Election Fund","zh":"语言偏好与总统选举基金"},"senior":{"en":"Language and Election Fund","zh":"语言和总统选举基金"}},"questions":[{"id":"irs_language_pref","type":"who","required":true,"options":[{"value":"me"},{"value":"spouse"},{"value":"none"}],"wording":{"general":{"en":"Would you like written communications from the IRS in a language other than English?","zh":"您是否希望国税局用英语以外的语言与您书面沟通？"},"senior":{"en":"Do you want letters from the IRS in a language other than English?","zh":"您希望国税局（IRS）用英语以外的语言给您写信吗？"}}},{"id":"irs_language","type":"text","required":false,"showIf":[{"field":"irs_language_pref","op":"ne","value":"none"}],"wording":{"general":{"en":"Which language?","zh":"哪种语言？"},"senior":{"en":"Which language?","zh":"什么语言？"}}},{"id":"pecf","type":"who","required":true,"options":[{"value":"me"},{"value":"spouse"},{"value":"none"}],"tips":{"general":[{"en":"**This does not increase your tax or reduce your refund.**","zh":"**不会增加您的税款，也不会减少您的退税。**"}],"senior":[{"en":"**This will NOT change your tax or your refund.** It only decides where $3 of government money goes.","zh":"**您不用多付钱，您的税和退税也不会变。**这只是决定政府的 3 美元用在哪里。"}]},"wording":{"general":{"en":"Would you like $3 to go to the Presidential Election Campaign Fund?","zh":"您是否愿意将 3 美元拨入总统选举竞选基金？"},"senior":{"en":"Do you want $3 to go to the Presidential Election Campaign Fund?","zh":"您愿意让国税局把 3 美元拨给总统选举基金吗？"}}}]},{"n":12,"title":{"general":{"en":"Optional Questions (for statistics only)","zh":"选填问题（仅用于统计）"},"senior":{"en":"Optional Questions (for statistics only)","zh":"选填问题（仅用于统计）"}},"intro":{"general":{"en":"These questions are **optional**. Your answers are **not** part of your tax return and are **not** sent to the IRS.","zh":"以下问题为**选填**。您的回答**不属于**报税表内容，也**不会**提交给国税局。"},"senior":{"en":"These questions are **optional**. Your answers are **not** part of your tax return and are **not** sent to the IRS with your return.","zh":"以下问题**可以不回答**。您的回答**不属于**报税表，也**不会**和报税表一起寄给国税局。"}},"questions":[{"id":"opt_english_speak","type":"choice","required":false,"options":[{"value":"very_well","label":{"general":{"en":"Very well","zh":"很好"},"senior":{"en":"Very well","zh":"很好"}}},{"value":"well","label":{"general":{"en":"Well","zh":"较好"},"senior":{"en":"Well","zh":"还可以"}}},{"value":"not_well","label":{"general":{"en":"Not well","zh":"不太好"},"senior":{"en":"Not well","zh":"不太好"}}},{"value":"not_at_all","label":{"general":{"en":"Not at all","zh":"完全不会"},"senior":{"en":"Not at all","zh":"完全不会"}}},{"value":"prefer_not_to_answer","label":{"general":{"en":"Prefer not to answer","zh":"不愿回答"},"senior":{"en":"Prefer not to answer","zh":"不想回答"}}}],"wording":{"general":{"en":"How well can you carry on a conversation in English?","zh":"您用英语交谈的能力如何？"},"senior":{"en":"How well can you talk with someone in English?","zh":"您用英语和别人聊天的水平怎么样？"}}},{"id":"opt_english_read","type":"choice","required":false,"options":[{"value":"very_well","label":{"general":{"en":"Very well","zh":"很好"},"senior":{"en":"Very well","zh":"很好"}}},{"value":"well","label":{"general":{"en":"Well","zh":"较好"},"senior":{"en":"Well","zh":"还可以"}}},{"value":"not_well","label":{"general":{"en":"Not well","zh":"不太好"},"senior":{"en":"Not well","zh":"不太好"}}},{"value":"not_at_all","label":{"general":{"en":"Not at all","zh":"完全不会"},"senior":{"en":"Not at all","zh":"完全不会"}}},{"value":"prefer_not_to_answer","label":{"general":{"en":"Prefer not to answer","zh":"不愿回答"},"senior":{"en":"Prefer not to answer","zh":"不想回答"}}}],"wording":{"general":{"en":"How well can you read a newspaper in English?","zh":"您阅读英文报纸的能力如何？"},"senior":{"en":"How well can you read a newspaper in English?","zh":"您看英文报纸的水平怎么样？"}}},{"id":"opt_household_disability","type":"choice","required":false,"options":[{"value":"yes","label":{"general":{"en":"Yes","zh":"是"},"senior":{"en":"Yes","zh":"有"}}},{"value":"no","label":{"general":{"en":"No","zh":"否"},"senior":{"en":"No","zh":"没有"}}},{"value":"prefer_not_to_answer","label":{"general":{"en":"Prefer not to answer","zh":"不愿回答"},"senior":{"en":"Prefer not to answer","zh":"不想回答"}}}],"wording":{"general":{"en":"Do you or any member of your household have a disability?","zh":"您或家庭成员中是否有人有残疾？"},"senior":{"en":"Does anyone in your home have a disability?","zh":"您家里有没有人有残疾？"}}},{"id":"opt_veteran","type":"choice","required":false,"options":[{"value":"yes","label":{"general":{"en":"Yes","zh":"是"},"senior":{"en":"Yes","zh":"是"}}},{"value":"no","label":{"general":{"en":"No","zh":"否"},"senior":{"en":"No","zh":"不是"}}},{"value":"prefer_not_to_answer","label":{"general":{"en":"Prefer not to answer","zh":"不愿回答"},"senior":{"en":"Prefer not to answer","zh":"不想回答"}}}],"wording":{"general":{"en":"Are you or your spouse a veteran of the U.S. Armed Forces?","zh":"您或配偶是否为美国退伍军人？"},"senior":{"en":"Are you or your spouse a U.S. military veteran?","zh":"您或您爱人是美国退伍军人吗？"}}},{"id":"opt_race_tp","type":"multi","required":false,"options":[{"value":"american_indian_alaska_native","label":{"general":{"en":"American Indian or Alaska Native","zh":"美洲原住民或阿拉斯加原住民"},"senior":{"en":"American Indian or Alaska Native","zh":"美洲原住民或阿拉斯加原住民"}}},{"value":"asian","label":{"general":{"en":"Asian","zh":"亚裔"},"senior":{"en":"Asian","zh":"亚裔"}}},{"value":"black_african_american","label":{"general":{"en":"Black or African American","zh":"黑人或非裔美国人"},"senior":{"en":"Black or African American","zh":"黑人或非裔美国人"}}},{"value":"hispanic_latino","label":{"general":{"en":"Hispanic or Latino","zh":"西班牙裔或拉丁裔"},"senior":{"en":"Hispanic or Latino","zh":"西班牙裔或拉丁裔"}}},{"value":"middle_eastern_north_african","label":{"general":{"en":"Middle Eastern or North African","zh":"中东或北非裔"},"senior":{"en":"Middle Eastern or North African","zh":"中东或北非裔"}}},{"value":"native_hawaiian_pacific_islander","label":{"general":{"en":"Native Hawaiian or Pacific Islander","zh":"夏威夷原住民或太平洋岛民"},"senior":{"en":"Native Hawaiian or Pacific Islander","zh":"夏威夷原住民或太平洋岛民"}}},{"value":"white","label":{"general":{"en":"White","zh":"白人"},"senior":{"en":"White","zh":"白人"}}},{"value":"prefer_not_to_answer","label":{"general":{"en":"Prefer not to answer","zh":"不愿回答"},"senior":{"en":"Prefer not to answer","zh":"不想回答"}}}],"wording":{"general":{"en":"What is your race and/or ethnicity? (Select all that apply)","zh":"您的种族和/或族裔？（可多选）"},"senior":{"en":"What is your race and/or ethnicity? (Choose all that apply)","zh":"您的种族或族裔是什么？（可以多选）"}}},{"id":"opt_race_sp","type":"multi","required":false,"options":[{"value":"american_indian_alaska_native","label":{"general":{"en":"American Indian or Alaska Native","zh":"美洲原住民或阿拉斯加原住民"},"senior":{"en":"American Indian or Alaska Native","zh":"美洲原住民或阿拉斯加原住民"}}},{"value":"asian","label":{"general":{"en":"Asian","zh":"亚裔"},"senior":{"en":"Asian","zh":"亚裔"}}},{"value":"black_african_american","label":{"general":{"en":"Black or African American","zh":"黑人或非裔美国人"},"senior":{"en":"Black or African American","zh":"黑人或非裔美国人"}}},{"value":"hispanic_latino","label":{"general":{"en":"Hispanic or Latino","zh":"西班牙裔或拉丁裔"},"senior":{"en":"Hispanic or Latino","zh":"西班牙裔或拉丁裔"}}},{"value":"middle_eastern_north_african","label":{"general":{"en":"Middle Eastern or North African","zh":"中东或北非裔"},"senior":{"en":"Middle Eastern or North African","zh":"中东或北非裔"}}},{"value":"native_hawaiian_pacific_islander","label":{"general":{"en":"Native Hawaiian or Pacific Islander","zh":"夏威夷原住民或太平洋岛民"},"senior":{"en":"Native Hawaiian or Pacific Islander","zh":"夏威夷原住民或太平洋岛民"}}},{"value":"white","label":{"general":{"en":"White","zh":"白人"},"senior":{"en":"White","zh":"白人"}}},{"value":"prefer_not_to_answer","label":{"general":{"en":"Prefer not to answer","zh":"不愿回答"},"senior":{"en":"Prefer not to answer","zh":"不想回答"}}}],"showIf":[{"field":"marital_status","op":"eq","value":"married"}],"wording":{"general":{"en":"What is your spouse''s race and/or ethnicity? (Select all that apply)","zh":"配偶的种族和/或族裔？（可多选）"},"senior":{"en":"What is your spouse''s race and/or ethnicity? (Choose all that apply)","zh":"您爱人的种族或族裔是什么？（可以多选）"}}}]},{"n":13,"title":{"general":{"en":"Additional Notes","zh":"补充说明"},"senior":{"en":"Anything Else?","zh":"其他"}},"questions":[{"id":"additional_notes","type":"longtext","required":false,"wording":{"general":{"en":"Anything else you''d like the volunteer to know?","zh":"还有其他需要告知志愿者的信息吗？"},"senior":{"en":"Is there anything else you want the volunteer to know?","zh":"还有什么想告诉志愿者的吗？"}}}]}]},{"n":9,"title":{"en":"Consent","zh":"同意书"},"sections":[{"n":14,"title":{"general":{"en":"Consent to Disclose Tax Return Information (Form 15080)","zh":"报税信息披露同意书"},"senior":{"en":"Permission to Share Your Tax Information Next Year (Form 15080)","zh":"同意明年共享您的报税资料"}},"intro":{"general":{"en":"**This consent is optional. Declining will not affect the tax preparation service you receive.**\n\nIf you consent, TaxSlayer (the VITA/TCE software provider) may make your tax return information available to **any** VITA/TCE site using TaxSlayer that you visit next filing season, so your return can be pre-filled.\n\nInformation disclosed includes: name, address, date of birth, phone, SSN, filing status, occupation, employer, income, deductions, and credits, plus your dependents'' names, SSNs, dates of birth, and relationship to you.\n\nThis consent is valid through **November 30, 2027**.\n\n**Note:** Once disclosed, federal law may not protect your information from further use or distribution.\n\nConsent is not needed for the site preparing your return this year; it only helps if you visit a **different** site next year.\n\nYou have the right to receive a signed copy of this form.","zh":"**此同意书为自愿签署。不同意不会影响我们为您提供报税服务。**\n\n如您同意，TaxSlayer（VITA/TCE 报税软件提供商）可将您的报税信息提供给您明年前往的**任何**使用 TaxSlayer 的 VITA/TCE 报税点，用于自动预填。\n\n披露的信息包括：姓名、地址、出生日期、电话、社会安全号码、报税身份、职业、雇主、收入、扣除项和抵免项，以及受抚养人的姓名、社会安全号码、出生日期和与您的关系。\n\n本同意有效期至 **2027 年 11 月 30 日**。\n\n**注意：**信息披露后，联邦法律可能无法防止其被进一步使用或传播。\n\n今年为您报税的站点无需此同意；仅在您明年前往**其他**站点时有用。\n\n您有权获得本表签署后的副本。"},"senior":{"en":"**This page is optional. You will still get tax help if you say No.**\n\nIf you say **Yes**: next year you can go to **any** free tax help site that uses TaxSlayer software, and your information from this year will already be filled in. This saves time.\n\nInformation that will be shared: your name, address, birthday, phone, Social Security number, filing status, job, employer, income, deductions, credits, and your dependents'' names, SSNs, birthdays, and relationship to you.\n\nThis permission lasts until **November 30, 2027**.\n\n**Important:** Once shared, federal law may not protect this information from further use.\n\nYou do **not** need to say Yes for the site helping you this year. This only helps if you go to a **different** site next year.\n\nYou have the right to get a signed copy of this form.","zh":"**此页可选。即使您选\"不同意\"，我们也照样帮您报税。**\n\n如果您同意：明年您去**任何一个**使用 TaxSlayer 软件的免费报税点，今年的资料都会自动填好，可以节省时间。\n\n会共享的资料：您的姓名、地址、生日、电话、社安号码、报税身份、工作、工作单位、收入、减税和补助项目，以及您家属的姓名、社安号码、生日和与您的关系。\n\n这个同意有效期到 **2027 年 11 月 30 日**。\n\n**注意：**资料共享出去以后，联邦法律可能无法保护它不被再次使用。\n\n今年帮您报税的地方，**不需要**您同意这一页。只有明年您去**别的**报税点时，这一页才有用。\n\n您有权拿到一份签过名的表格副本。"}},"questions":[{"id":"gcf_consent","type":"choice","required":false,"options":[{"value":"yes","label":{"general":{"en":"I consent","zh":"同意"},"senior":{"en":"Yes, I agree","zh":"同意"}}},{"value":"no","label":{"general":{"en":"I do not consent","zh":"不同意"},"senior":{"en":"No, I do not agree","zh":"不同意"}}}],"tips":{"general":[{"en":"If you wish to limit the duration or scope of the disclosure, choose **No**.","zh":"如希望缩短有效期或限制披露范围，请选择**不同意**。"}],"senior":[{"en":"If you want the permission to last a shorter time, or share less information, choose **No**.","zh":"如果您想让有效期更短，或者只共享一部分资料，请选**不同意**。"}]},"wording":{"general":{"en":"Do you consent to this disclosure?","zh":"您是否同意上述信息披露？"},"senior":{"en":"Do you agree to let your tax information be shared this way?","zh":"您同意用这种方式共享您的报税资料吗？"}}},{"id":"gcf_tp_signature","type":"signature","required":false,"showIf":[{"field":"gcf_consent","op":"eq","value":"yes"}],"wording":{"general":{"en":"Primary taxpayer signature (type full name)","zh":"主报税人签名（输入全名）"},"senior":{"en":"Type your full name to sign","zh":"请输入您的全名作为签名"}}},{"id":"gcf_tp_date","type":"date","required":false,"showIf":[{"field":"gcf_consent","op":"eq","value":"yes"}],"wording":{"general":{"en":"Date","zh":"日期"},"senior":{"en":"Date","zh":"日期"}}},{"id":"gcf_sp_signature","type":"signature","required":false,"showIf":[{"field":"gcf_consent","op":"eq","value":"yes"},{"field":"marital_status","op":"eq","value":"married"}],"wording":{"general":{"en":"Secondary taxpayer (spouse) signature (type full name)","zh":"配偶签名（输入全名）"},"senior":{"en":"Spouse: type your full name to sign","zh":"请您爱人输入全名作为签名"}}},{"id":"gcf_sp_date","type":"date","required":false,"showIf":[{"field":"gcf_sp_signature","op":"filled"}],"wording":{"general":{"en":"Spouse signature date","zh":"配偶签名日期"},"senior":{"en":"Spouse date","zh":"您爱人签名的日期"}}}],"footer":{"general":{"en":"If you believe your tax return information has been disclosed or used improperly, contact TIGTA at **1-800-366-4484** or https://www.tigta.gov/reportcrime-misconduct","zh":"如您认为您的报税信息被不当披露或使用，请联系 TIGTA：**1-800-366-4484**，或访问上述网址。"},"senior":{"en":"If you think your tax information was shared or used wrongly, call TIGTA: **1-800-366-4484**, or visit https://www.tigta.gov/reportcrime-misconduct","zh":"如果您认为您的报税资料被错误共享或使用，请打电话给 TIGTA：**1-800-366-4484**，或访问上面的网址。"}}}]}],"fixedOptions":{"who":{"options":[{"value":"me","label":{"general":{"en":"Me","zh":"本人"},"senior":{"en":"Me","zh":"我自己"}}},{"value":"spouse","label":{"general":{"en":"My spouse","zh":"配偶"},"senior":{"en":"My spouse","zh":"我爱人"}}},{"value":"none","label":{"general":{"en":"No one","zh":"均无"},"senior":{"en":"No one","zh":"都没有"}}}],"spouseShowIf":[{"field":"marital_status","op":"eq","value":"married"}]},"yesno":{"options":[{"value":"yes","label":{"general":{"en":"Yes","zh":"是"},"senior":{"en":"Yes","zh":"是"}}},{"value":"no","label":{"general":{"en":"No","zh":"否"},"senior":{"en":"No","zh":"否"}}},{"value":"not_sure","label":{"general":{"en":"I''m not sure","zh":"不确定"},"senior":{"en":"I''m not sure","zh":"我不确定"}}}]}},"materials":[{"id":"photo_id","label":{"en":"Photo ID","zh":"带照片身份证件"}},{"id":"ssn_itin","label":{"en":"SSN / ITIN","zh":"社会安全号码 / ITIN"}},{"id":"green_card","label":{"en":"Green card","zh":"绿卡"}},{"id":"birth_certificate","label":{"en":"Birth certificate","zh":"出生证明"}},{"id":"w2","label":{"en":"W-2","zh":"W-2 表"}},{"id":"1099nec","label":{"en":"1099-NEC","zh":"1099-NEC 表"}},{"id":"1099misc","label":{"en":"1099-MISC","zh":"1099-MISC 表"}},{"id":"1099int","label":{"en":"1099-INT","zh":"1099-INT 表"}},{"id":"1098t","label":{"en":"1098-T","zh":"1098-T 表"}},{"id":"1095a","label":{"en":"1095-A","zh":"1095-A 表"}},{"id":"prior_year_1040","label":{"en":"Prior-year return (1040)","zh":"去年的报税表（1040）"}}]}'::jsonb);
